<script setup>
import AuditEvidence from './AuditEvidence.vue';
import {date,taxId,money} from '../lib/format';
const props=defineProps({document:{type:Object,required:true},booked:{default:null},findings:{default:()=>[]}});
const decimal=v=>v===null||v===undefined||v===''?'—':Number(v).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:6});
const bookedItem=item=>props.booked?.items?.find(b=>String(b.number)===String(item.item_number));
const unsupported=item=>item.calculation_scope==='unsupported_special'||props.findings.some(f=>f.rule_code==='COVERAGE-IBSCBS-001'&&f.document_ref===props.document.document_ref&&Number(f.item_number)===Number(item.item_number));
const calculated=(item,field)=>item.calculation_scope==='bookkeeping_only'?'Sem XML original':unsupported(item)?'Não recalculado':item.calculation_scope==='absent'?'Sem grupo IBS/CBS':decimal(item[field]);
</script>
<template><div class="audit-document"><dl class="document-fields"><div><dt>Emissão</dt><dd>{{date(document.issued_at)}}</dd></div><div><dt>Série</dt><dd>{{document.series||'—'}}</dd></div><div><dt>Operação</dt><dd>{{document.direction==='entrada'?'Entrada':document.direction==='saida'?'Saída':document.direction||'—'}}</dd></div><div><dt>Emitente</dt><dd>{{taxId(document.issuer_tax_id)}}</dd></div><div><dt>Destinatário</dt><dd>{{taxId(document.recipient_tax_id)}}</dd></div><div><dt>Origem</dt><dd>{{booked?'Documento escriturado #'+booked.id+' · versão '+booked.version:'Auditoria avulsa'}}</dd></div></dl><p class="document-key"><strong>Chave:</strong> {{document.access_key||'Não informada'}}</p>
<h3>Valores comparados</h3><p v-if="document.origin==='bookkeeping'" class="message warning">Dados da escrituração: XML original indisponível. Nenhum valor é apresentado como recálculo fiscal.</p><div class="table-scroll"><table><thead><tr><th>Informação</th><th>Original XML</th><th>Escrituração no retrato</th></tr></thead><tbody><tr><td>Total do documento</td><td>{{document.origin==='bookkeeping'?'Indisponível':decimal(document.total_value)}}</td><td>{{booked?money(booked.total_cents):'Sem vínculo'}}</td></tr><tr><td>IBS informado</td><td>{{decimal(document.ibs_value)}}</td><td>Ver tributos da escrituração</td></tr><tr><td>CBS informada</td><td>{{decimal(document.cbs_value)}}</td><td>Ver tributos da escrituração</td></tr></tbody></table></div>
<h3>Itens e memória de cálculo</h3><p v-if="!document.items?.length">Este modelo possui cobertura de leitura, sem recálculo de itens.</p><details v-for="item in document.items" :key="item.item_number" class="item-detail"><summary>Item {{item.item_number}} · {{item.description||item.product_code||'Sem descrição'}} · NCM {{item.ncm||'—'}}</summary><dl class="document-fields"><div><dt>CFOP / EX</dt><dd>{{item.cfop||'—'}} / {{item.ex_code||'—'}}</dd></div><div><dt>CST / cClassTrib no XML</dt><dd>{{item.actual_cst||'—'}} / {{item.actual_cclass_trib||'—'}}</dd></div><div><dt>CST / cClassTrib no catálogo</dt><dd>{{item.expected_cst||'—'}} / {{item.expected_cclass_trib||'—'}}</dd></div></dl><div class="table-scroll"><table><thead><tr><th>Valor em reais</th><th>XML</th><th>Recalculado</th><th>Escrituração no retrato</th></tr></thead><tbody><tr><td>Produtos</td><td>{{document.origin==='bookkeeping'?'Indisponível':decimal(item.product_value)}}</td><td>—</td><td>{{decimal(bookedItem(item)?.total)}}</td></tr><tr><td>Base IBS/CBS</td><td>{{decimal(item.ibs_cbs_base_xml)}}</td><td>{{calculated(item,'ibs_cbs_base_recalculated')}}</td><td>—</td></tr><tr><td>IBS</td><td>{{decimal(item.ibs_xml)}}</td><td>{{calculated(item,'ibs_recalculated')}}</td><td>—</td></tr><tr><td>CBS</td><td>{{decimal(item.cbs_xml)}}</td><td>{{calculated(item,'cbs_recalculated')}}</td><td>—</td></tr></tbody></table></div><p>{{unsupported(item)?'Cenário especial: recálculo tributário não certificado. Consulte o achado de cobertura.':'Conferência aritmética assistida; arredondamento comercial para centavos. A fórmula recuperada exige revisão de vigência e cenário.'}}</p><details><summary>Componentes da base</summary><AuditEvidence :value="item.tax_components"/></details><details><summary>Parâmetros e evidência do catálogo</summary><AuditEvidence :value="item.catalog_match"/></details><details><summary>Quantidades, tributos e rastreabilidade</summary><AuditEvidence :value="item.details"/></details></details>
<details><summary>Participantes, endereços, pagamentos, transporte e protocolo</summary><AuditEvidence :value="document.normalized"/></details><details v-if="booked"><summary>Valores escriturados preservados no retrato</summary><AuditEvidence :value="booked"/></details></div></template>
<style scoped>.audit-document{padding:12px 0}.document-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:12px 0}.document-fields dt{color:#688496;font-size:12px}.document-fields dd{margin:4px 0 0;font-weight:600;overflow-wrap:anywhere}.document-key{overflow-wrap:anywhere}.item-detail{padding:12px 0;border-top:1px solid #e2e8ec}.item-detail>summary{font-weight:600;cursor:pointer}.item-detail details{padding:8px 0}.audit-document h3{margin:16px 0 8px}.audit-document table td{font-variant-numeric:tabular-nums}@media(max-width:700px){.document-fields{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:450px){.document-fields{grid-template-columns:1fr}}
</style>
